SELECT COUNT(*) FROM badges as b, comments as c, posts as p, users as u WHERE c.UserId = u.Id AND b.UserId = u.Id AND p.Id = c.PostId AND b."Date">=CAST('2010-08-06 10:36:45' AS TIMESTAMP) AND b."Date"<=CAST('2014-09-12 07:19:35' AS TIMESTAMP) AND c.Score=0 AND p.ViewCount>=0 AND p.AnswerCount<=5 AND p.CommentCount<=12 AND p.FavoriteCount>=0
